 SwingMatch m;Keyboard keyboard;Gamepad pad,replacement;InputSettings.BackgroundBehavior background;bool had,restored;string saved,folder;int errors,pump;Vector2 inject;readonly StringBuilder log=new StringBuilder();void Check(bool ok,string label){log.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+s);}}
 IEnumerator PumpTrial(int direction){m.SetupScreen();m.setup.count=1;m.NormalizeSetup();m.setup.players[0].source=BowlingSource.Keyboard;Check(m.StartMatch(),"physical pump trial starts mode="+direction);while(m.Phase==SwingPhase.Loading)yield return null;pump=direction;Time.timeScale=3;yield return new WaitForSeconds(13);pump=0;}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("SwingFocusedEvidence");background=InputSystem.settings.backgroundBehavior;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.EnableDevice(keyboard);yield return SportsProbeScene.Ensure<SwingMatch>("TruckGiantSwing");m=FindAnyObjectByType<SwingMatch>();yield return null;m.setup.players[0].color=new Color(1,.25f,.7f);had=PlayerPrefs.HasKey(m.PreferenceKey);saved=PlayerPrefs.GetString(m.PreferenceKey);Application.logMessageReceived+=Error;yield return PumpTrial(-1);float bad=m.Energy;yield return PumpTrial(1);float good=m.Energy;Check(good>bad*2+200,"timed physical pumping builds more energy than opposing motion bad="+bad+" good="+good);Check(good<SwingRules.EnergyCap+180,"same bounded pump-energy cap");Capture(1280,720,"pump");Capture(1920,1080,"pump");pad=InputSystem.AddDevice<Gamepad>();m.setup.players[0].source=BowlingSource.WholeController;Check(m.Assign(0,pad),"turn owner gets independent mapped source");InputSystem.QueueStateEvent(pad,new GamepadState());yield return null;InputSystem.RemoveDevice(pad);pad=null;yield return null;var seat=m.seat.position;var truck=m.truck.body.position;float age=m.Age;yield return new WaitForSecondsRealtime(.15f);Check(m.Paused&&seat==m.seat.position&&truck==m.truck.body.position&&age==m.Age,"disconnect preserves real hinged seat and mounted truck");replacement=InputSystem.AddDevice<Gamepad>();Check(m.Assign(0,replacement),"explicit release-source replacement accepted");InputSystem.QueueStateEvent(replacement,new GamepadState{rightTrigger=1});yield return null;m.Resume();yield return null;yield return null;Check(!m.setup.players[0].released&&m.commands[0]==Vector2.zero,"held replacement input requires deliberate neutral");InputSystem.QueueStateEvent(replacement,new GamepadState());yield return null;yield return null;Check(m.setup.players[0].released,"neutral replacement arms fresh controls");m.setup.players[0].source=BowlingSource.Keyboard;pump=1;Time.timeScale=3;float deadline=Time.realtimeSinceStartup+20;while(!(m.Angle< -25&&m.Angle> -48&&m.seat.angularVelocity.x<-.3f)&&m.Phase==SwingPhase.Pumping&&Time.realtimeSinceStartup<deadline)yield return null;pump=0;var v=m.seat.GetPointVelocity(m.truck.body.worldCenterOfMass);m.Release(Vector2.up);Check(m.Phase==SwingPhase.Flight&&(m.ReleaseVelocity-v).magnitude<.001f&&(m.truck.body.linearVelocity-v).magnitude<.001f,"release inherits actual point velocity exactly without added impulse");inject=Vector2.up;yield return new WaitForSeconds(.35f);Check(m.CorrectionSpent==0,"held acceleration does not spend range aftertouch at release");inject=Vector2.zero;yield return new WaitForSeconds(.1f);var vertical=m.truck.body.linearVelocity.y;float start=m.FlightAge;inject=new Vector2(1,1);yield return new WaitForSeconds(.6f);float elapsed=m.FlightAge-start;Check(m.CorrectionSpent>0&&m.CorrectionSpent<=SwingRules.Aftertouch+.001f,"fresh range and lateral correction use bounded shared budget");Check(Mathf.Abs(m.truck.body.linearVelocity.y-(vertical+Physics.gravity.y*elapsed))<.4f,"aftertouch supplies no vertical lift or hovering");Capture(1280,720,"flight");inject=Vector2.zero;float until=Time.realtimeSinceStartup+25;while(m.Phase==SwingPhase.Flight&&Time.realtimeSinceStartup<until)yield return null;Check(m.Phase==SwingPhase.Landing,"actual released truck reaches real ground contact");int locks=m.Locks,points=m.points[0];m.truck.body.AddForce(new Vector3(0,8,12),ForceMode.VelocityChange);inject=Vector2.one;yield return new WaitForSeconds(1);Check(m.Locks==locks&&m.points[0]==points,"physical rebound and held input cannot rescore first landing");inject=Vector2.zero;until=Time.realtimeSinceStartup+15;while(m.Phase!=SwingPhase.Replay&&Time.realtimeSinceStartup<until)yield return null;Check(m.replay.Playing&&m.truck.body.isKinematic&&!m.truck.body.detectCollisions,"recorded replay has no live collision authority");var paint=m.replay.ghosts[0].GetComponentsInChildren<Renderer>().First(r=>r.name=="Cab");var block=new MaterialPropertyBlock();paint.GetPropertyBlock(block);Check(Vector4.Distance(block.GetColor("_BaseColor"),m.setup.players[0].color)<.01f,"recorded truck preserves the current participant paint");Check(m.windAudio.clip!=null&&m.mechanicalAudio.clip!=null,"vendor wind and mechanical audio loops bound without additional listeners");m.ExtraAction("replayangle");m.ExtraAction("replayspeed");Check(m.replay.Angle==1&&m.replay.Speed==1,"recorded angle and playback speed controls work");m.ExtraAction("replayrewind");Check(m.replay.Cursor>=0,"bounded replay rewind");yield return new WaitForSeconds(1.1f);m.ExtraAction("replayskip");Check(!m.replay.Playing,"skip exits replay safely");m.SetupScreen();m.setup.count=2;m.NormalizeSetup();m.setup.players[0].source=m.setup.players[1].source=BowlingSource.WholeController;m.setup.players[0].pad=m.setup.players[1].pad=replacement;Check(m.ValidateSources(out _),"sequential turn owners may reuse one whole controller");m.AllBots();Check(m.StartMatch()&&m.Round==1&&m.Locks==0&&m.points[0]==0,"rematch resets attempts and score retaining setup");m.SetupScreen();RestorePrefs();SportsNavigation.FrontEnd();yield return null;yield return null;var f=FindAnyObjectByType<SportsFrontEnd>();f.Action("cataloguenext");f.Action("cataloguenext");Check(f.catalogue.Pages==3&&f.catalogue.cards[16].activeInHierarchy,"seventeenth sport is reachable on third catalogue page");f.Action("swing");yield return null;yield return null;m=FindAnyObjectByType<SwingMatch>();Check(m!=null,"collection loads native saved Swing scene");m.AllBots();Check(m.StartMatch(),"collection-returned Swing starts");m.SetupScreen();log.AppendLine("ERRORS="+errors+". Real PhysX joints, torque, release velocity, flight and contact; synthetic commands/virtual sources; camera-only renders. No hardware/human testing.");File.WriteAllText(folder+"/result.txt",log.ToString());Debug.Log("SWING_FOCUSED_COMPLETE "+log);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void FixedUpdate(){if(m==null||!m.Live)return;if(m.Phase==SwingPhase.Pumping&&pump!=0){float omega=m.seat.angularVelocity.x;float y=Mathf.Abs(omega)>.015f?-Mathf.Sign(omega):1;m.commands[m.Current]=new Vector2(0,y*pump);}else if(m.Phase==SwingPhase.Flight)m.commands[m.Current]=inject;}
 void Capture(int width,int height,string phase){var c=m.cameraRig.view;var active=RenderTexture.active;var old=c.targetTexture;var rt=RenderTexture.GetTemporary(width,height,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var texture=new Texture2D(width,height,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,width,height),0,0);texture.Apply();File.WriteAllBytes(folder+"/camera-only-"+phase+"-"+width+".png",texture.EncodeToPNG());c.targetTexture=old;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);Destroy(texture);}
